// Generates the design tokens for both clients from design/tokens.json:
//   - the token block of src/app/globals.css (between the `tokens:start` / `tokens:end` markers)
//   - ios/Hyperanchor/Design/Tokens.swift
// Usage: npm run tokens            (write)
//        npm run tokens -- --check (fail if a generated file is out of date)

import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname } from "node:path";

const root = new URL("../", import.meta.url);
const SOURCE = new URL("design/tokens.json", root);
const CSS = new URL("src/app/globals.css", root);
const SWIFT = new URL("ios/Hyperanchor/Design/Tokens.swift", root);
const START = "/* tokens:start — generated by `npm run tokens` from design/tokens.json; edit that file, not this block */";
const END = "/* tokens:end */";

const tokens = JSON.parse(await readFile(SOURCE, "utf8"));
const check = process.argv.includes("--check");

// Display order of the theme colors, in groups (blank line between groups in CSS, MARK in Swift).
const GROUPS = [
  ["Surfaces", ["canvas", "surface", "surface-2", "surface-3", "elevated", "glass", "scrim"]],
  ["Text and lines", ["ink", "ink-2", "ink-3", "ink-4", "line", "line-2", "check-ring"]],
  ["Primary buttons", ["primary", "primary-hover", "on-primary"]],
  ["Accent", ["on-accent", "heat-0"]],
  ["Rises and drops (analytics), destructive actions", ["green-ink", "green-soft", "red-ink", "red-soft"]],
];
const grouped = GROUPS.flatMap(([, keys]) => keys);
const missing = Object.keys(tokens.color).filter((k) => !grouped.includes(k));
if (missing.length) throw new Error(`Add to GROUPS in scripts/tokens.mjs: ${missing.join(", ")}`);

const accents = tokens.accent.options;
const accentKeys = Object.keys(accents[tokens.accent.default].light);

// ── CSS ─────────────────────────────────────────────────────────────────────

const px = (n) => (n === 0 ? "0" : `${n}px`);
const cssShadow = (layers) =>
  layers.map((l) => [px(l.x), px(l.y), px(l.blur), ...(l.spread ? [px(l.spread)] : []), l.color].join(" ")).join(", ");

function cssBlock(selector, lines) {
  return `${selector} {\n${lines.map((l) => (l ? `  ${l}` : "")).join("\n")}\n}`;
}

function themeLines(theme) {
  const out = [`color-scheme: ${theme};`, ""];
  const def = accents[tokens.accent.default][theme];
  for (const [title, keys] of GROUPS) {
    if (title === "Accent") {
      for (const k of accentKeys) out.push(`--${k}: ${def[k]};${tokens.accent.notes[k] ? ` /* ${tokens.accent.notes[k]} */` : ""}`);
    }
    for (const k of keys) {
      const c = tokens.color[k];
      out.push(`--${k}: ${c[theme]};${c.note ? ` /* ${c.note} */` : ""}`);
    }
    out.push("");
  }
  if (theme === "light") {
    for (const [k, v] of Object.entries(tokens.radius)) out.push(`--radius-${k}: ${v}px;`);
    out.push("");
  }
  for (const [k, s] of Object.entries(tokens.shadow)) out.push(`--shadow-${k}: ${cssShadow(s[theme])};`);
  return out;
}

const accentLines = (name, theme) => accentKeys.map((k) => `--${k}: ${accents[name][theme][k]};`);

function css() {
  const blocks = [cssBlock(":root", themeLines("light"))];
  for (const name of Object.keys(accents)) if (name !== tokens.accent.default) blocks.push(cssBlock(`:root[data-accent="${name}"]`, accentLines(name, "light")));
  blocks.push(cssBlock(':root[data-theme="dark"]', themeLines("dark")));
  for (const name of Object.keys(accents))
    if (name !== tokens.accent.default) blocks.push(cssBlock(`:root[data-theme="dark"][data-accent="${name}"]`, accentLines(name, "dark")));
  return `${START}\n${blocks.join("\n\n")}\n${END}`;
}

// ── Swift ───────────────────────────────────────────────────────────────────

const camel = (k) => k.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase());
const num = (n) => (Number.isInteger(n) ? String(n) : String(n));

function rgba(value) {
  const hex = value.match(/^#([0-9a-f]{6})$/i);
  if (hex) return `RGBA(hex: 0x${hex[1].toUpperCase()})`;
  const fn = value.match(/^rgba\(\s*(\d+),\s*(\d+),\s*(\d+),\s*([\d.]+)\s*\)$/);
  if (fn) {
    const h = [fn[1], fn[2], fn[3]].map((c) => Number(c).toString(16).padStart(2, "0")).join("").toUpperCase();
    return `RGBA(hex: 0x${h}, opacity: ${fn[4]})`;
  }
  throw new Error(`Unsupported color: ${value}`);
}

const themeColor = (light, dark) => `ThemeColor(light: ${rgba(light)}, dark: ${rgba(dark)})`;
const doc = (note, indent) => (note ? `${indent}/// ${note[0].toUpperCase()}${note.slice(1)}.\n` : "");
const swiftShadow = (layers, indent) =>
  `[\n${layers.map((l) => `${indent}    ShadowLayer(x: ${num(l.x)}, y: ${num(l.y)}, blur: ${num(l.blur)}, spread: ${num(l.spread)}, color: ${rgba(l.color)}),`).join("\n")}\n${indent}]`;

function swift() {
  const names = Object.keys(accents);
  const lines = [];
  const p = (s = "") => lines.push(s);
  p("// Generated by `npm run tokens` from design/tokens.json — do not edit by hand.");
  p("// The web gets the same values as CSS variables in src/app/globals.css.");
  p();
  p("import CoreGraphics");
  p();
  p("/// An sRGB color with opacity, components 0…1.");
  p("struct RGBA: Sendable, Hashable {");
  p("    let red: Double");
  p("    let green: Double");
  p("    let blue: Double");
  p("    let opacity: Double");
  p();
  p("    init(hex: UInt32, opacity: Double = 1) {");
  p("        red = Double((hex >> 16) & 0xFF) / 255");
  p("        green = Double((hex >> 8) & 0xFF) / 255");
  p("        blue = Double(hex & 0xFF) / 255");
  p("        self.opacity = opacity");
  p("    }");
  p("}");
  p();
  p("/// A color in the light and the dark theme.");
  p("struct ThemeColor: Sendable, Hashable {");
  p("    let light: RGBA");
  p("    let dark: RGBA");
  p("}");
  p();
  p("/// One layer of a CSS-style box shadow (a non-zero `spread` with no blur draws a hairline ring).");
  p("struct ShadowLayer: Sendable, Hashable {");
  p("    let x: CGFloat");
  p("    let y: CGFloat");
  p("    let blur: CGFloat");
  p("    let spread: CGFloat");
  p("    let color: RGBA");
  p("}");
  p();
  p("struct ThemeShadow: Sendable, Hashable {");
  p("    let light: [ShadowLayer]");
  p("    let dark: [ShadowLayer]");
  p("}");
  p();
  p("/// The accent-dependent colors.");
  p("struct AccentPalette: Sendable, Hashable {");
  for (const k of accentKeys) p(`${doc(tokens.accent.notes[k], "    ")}    let ${camel(k)}: ThemeColor`);
  p("}");
  p();
  p("/// The accent people can choose in Settings.");
  p("enum AccentChoice: String, CaseIterable, Identifiable, Sendable {");
  p(`    case ${names.join(", ")}`);
  p();
  p(`    static let \`default\`: AccentChoice = .${tokens.accent.default}`);
  p();
  p("    var id: String { rawValue }");
  p();
  p("    var label: String {");
  p("        switch self {");
  for (const n of names) p(`        case .${n}: "${accents[n].label}"`);
  p("        }");
  p("    }");
  p();
  p("    /// The light-theme accent, for showing the choice itself.");
  p("    var swatch: RGBA {");
  p("        switch self {");
  for (const n of names) p(`        case .${n}: ${rgba(accents[n].swatch)}`);
  p("        }");
  p("    }");
  p();
  p("    var palette: AccentPalette {");
  p("        switch self {");
  for (const n of names) {
    p(`        case .${n}:`);
    p("            AccentPalette(");
    accentKeys.forEach((k, i) => p(`                ${camel(k)}: ${themeColor(accents[n].light[k], accents[n].dark[k])}${i < accentKeys.length - 1 ? "," : ""}`));
    p("            )");
  }
  p("        }");
  p("    }");
  p("}");
  p();
  p("enum Tokens {");
  for (const [title, keys] of GROUPS) {
    p(`    // MARK: ${title}`);
    p();
    for (const k of keys) {
      const c = tokens.color[k];
      p(`${doc(c.note, "    ")}    static let ${camel(k)} = ${themeColor(c.light, c.dark)}`);
    }
    p();
  }
  p("    // MARK: Radii (points)");
  p();
  p("    enum Radius {");
  for (const [k, v] of Object.entries(tokens.radius)) p(`        static let ${camel(k)}: CGFloat = ${v}`);
  p("    }");
  p();
  p("    // MARK: Shadows");
  p();
  p("    enum Shadow {");
  for (const [k, s] of Object.entries(tokens.shadow)) {
    p(`        static let ${camel(k)} = ThemeShadow(`);
    p(`            light: ${swiftShadow(s.light, "            ")},`);
    p(`            dark: ${swiftShadow(s.dark, "            ")}`);
    p("        )");
  }
  p("    }");
  p("}");
  return lines.join("\n") + "\n";
}

// ── Write ───────────────────────────────────────────────────────────────────

const oldCss = await readFile(CSS, "utf8");
const a = oldCss.indexOf(START);
const b = oldCss.indexOf(END);
if (a < 0 || b < a) throw new Error(`Markers not found in ${CSS.pathname}`);
const newCss = oldCss.slice(0, a) + css() + oldCss.slice(b + END.length);
const newSwift = swift();
const oldSwift = await readFile(SWIFT, "utf8").catch(() => "");

const stale = [];
if (newCss !== oldCss) stale.push("src/app/globals.css");
if (newSwift !== oldSwift) stale.push("ios/Hyperanchor/Design/Tokens.swift");

if (check) {
  if (stale.length) {
    console.error(`Out of date: ${stale.join(", ")}. Run npm run tokens.`);
    process.exit(1);
  }
  console.log("Tokens are up to date.");
} else {
  await writeFile(CSS, newCss);
  await mkdir(dirname(SWIFT.pathname), { recursive: true });
  await writeFile(SWIFT, newSwift);
  console.log(stale.length ? `Updated ${stale.join(", ")}` : "Tokens are up to date.");
}
